function frame(ms){const rawDt=last?Math.max(0,(ms-last)/1000):0;const dt=Math.min(rawDt,.05);last=ms;t+=dt;if(mode==='play'&&ready){walking=false;if(!blocked()){state.elapsed+=dt;const dx=joy.x+Number(keys.has('right'))-Number(keys.has('left')),dy=joy.y+Number(keys.has('down'))-Number(keys.has('up'));const beforeX=state.x,beforeY=state.y;walking=move(state,dx,dy,dt);const travelled=Math.hypot(state.x-beforeX,state.y-beforeY);if(walking){walkPhase+=travelled/104;if(walkPhase-footAt>.39){footAt=walkPhase;beep(state.inside?75:55,.045,.012);}}tickCombat(state,combat,dt);if(Math.hypot(aim.x,aim.y)>.12||mouseAim){aimAngle(state,combat,aim.x,aim.y);const shot=fire(state,combat);if(shot){beep(shot.melee?80:115,shot.melee?.08:.14,shot.melee?.03:.1);if(shot.hit)beep(260,.06,.03);}}if(state.health<=0&&!downedShown){downedShown=true;persist();openPanel('downed');}if(t-saveAt>2){persist();saveAt=t;}updateHUD();}draw();$('guide').hidden=t>guideUntil||blocked();if(t>noticeUntil)$('notification').hidden=true;if(t>radioUntil)$('radio-message').hidden=true;$('fps').hidden=!prefs.fps;frameCount++;frameTime+=rawDt;if(frameTime>.7){$('fps').textContent=Math.round(frameCount/frameTime)+' FPS';frameCount=0;frameTime=0;}}requestAnimationFrame(frame);}
async function preload(){const files={map:'assets/clinic-v2.webp',infected:'assets/infected-v1.png',garageGround:'assets/garage-ground-v1.webp',garageBuilding:'assets/garage-building-v1.webp',garageInterior:'assets/garage-interior-v1.webp',garageProps:'assets/garage-props-v1.webp'};for(const dir of ['south','west','east','north'])for(let f=0;f<3;f++)files[dir+'-'+f]='assets/hero/'+dir+'-'+f+'.png';let count=0;try{await Promise.all(Object.entries(files).map(([key,url])=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{assets[key]=img;$('load-progress').style.width=(++count/Object.keys(files).length*100)+'%';resolve();};img.onerror=()=>reject(new Error(url));img.src=url;})));assets.garageBuilding._crop=ART.building;assets.garageInterior._crop=ART.interior;ready=true;$('loading').hidden=true;resize();setMenu();}catch(error){$('loading-label').textContent='НЕ УДАЛОСЬ ЗАГРУЗИТЬ ГРАФИКУ. НАЖМИ, ЧТОБЫ ПОВТОРИТЬ.';$('loading').onclick=()=>{location.reload();};console.error('Asset load failed:',error.message);}}
const aimStick=$('aim-stick');
function updateAim(e){if(e.pointerId!==aimPointer||blocked())return;const box=aimStick.getBoundingClientRect(),radius=box.width*.32;let x=e.clientX-box.left-box.width/2,y=e.clientY-box.top-box.height/2;const length=Math.hypot(x,y);if(length>radius){x*=radius/length;y*=radius/length;}aim={x:x/radius,y:y/radius};$('aim-knob').style.transform=`translate(${x}px,${y}px)`;}
aimStick.addEventListener('pointerdown',e=>{if(mode!=='play'||blocked())return;e.preventDefault();aimPointer=e.pointerId;aimStick.setPointerCapture(e.pointerId);if(prefs.sound){ensureAudio();updateAudio();}updateAim(e);});aimStick.addEventListener('pointermove',updateAim);
for(const event of ['pointerup','pointercancel','lostpointercapture'])aimStick.addEventListener(event,e=>{if(e.pointerId===aimPointer){aimPointer=null;aim={x:0,y:0};$('aim-knob').style.transform='translate(0,0)';}});
canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||mode!=='play'||blocked())return;mouseAim=true;canvas.setPointerCapture(e.pointerId);aim={x:cam.x+e.offsetX/window.innerWidth*cam.w-state.x,y:cam.y+e.offsetY/window.innerHeight*cam.h-state.y};});canvas.addEventListener('pointermove',e=>{if(!mouseAim)return;aim={x:cam.x+e.offsetX/window.innerWidth*cam.w-state.x,y:cam.y+e.offsetY/window.innerHeight*cam.h-state.y};});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>{mouseAim=false;aim={x:0,y:0};});
